function executeSkill(context) {
  var caster = context.piece;
  var player = battle.players.find(function(item) { return item.playerId === caster.ownerPlayerId; });
  if (!player) return { success: false, message: '未找到玩家' };
  if (!player.hand) player.hand = [];
  if (player.hand.length > 7) return { success: false, message: '手牌需要至少3个空位才能发动圣光汲取' };
  var target = selectTarget({ type: 'piece', range: 99, filter: 'ally' });
  if (!target || target.needsTargetSelection) return target;
  var shield = target.statusTags && target.statusTags.find(function(tag) { return tag.type === 'divine-shield'; });
  if (!shield) return { success: false, message: '目标没有圣盾' };
  removeStatusEffectById(target.instanceId, shield.id);
  removeRuleById(target.instanceId, 'rule-divine-shield');
  var smiteAdded = addCardToHand('holy-smite', player.playerId);
  var healAdded = addCardToHand('holy-heal', player.playerId);
  if (!smiteAdded || !healAdded) return { success: false, message: '圣光汲取生成手牌失败' };
  return { success: true, message: caster.name + '汲取了' + target.name + '的圣盾，获得圣光惩戒和圣光治疗' };
}
